static void vdec_msg_queue_core_work ( struct work_struct * work ) { struct vdec_msg_queue * msg_queue = container_of ( work , vdec_msg_queue , core_work ) ; struct mtk_vcodec_ctx * ctx = container_of ( msg_queue , mtk_vcodec_ctx , msg_queue ) ; struct mtk_vcodec_dev * dev = ctx -> dev ; struct vdec_lat_buf * lat_buf ; lat_buf = vdec_msg_queue_dqbuf ( & dev -> msg_queue_core_ctx ) ; ctx = lat_buf -> ctx ; mtk_vcodec_dec_enable_hardware ( ctx , MTK_VDEC_CORE ) ; mtk_vcodec_set_curr_ctx ( dev , ctx , MTK_VDEC_CORE ) ; lat_buf -> core_decode ( lat_buf ) ; mtk_vcodec_set_curr_ctx ( dev , NULL , MTK_VDEC_CORE ) ; mtk_vcodec_dec_disable_hardware ( ctx , MTK_VDEC_CORE ) ; vdec_msg_queue_qbuf ( & ctx -> msg_queue . lat_ctx , lat_buf ) ; if ( ! list_empty ( & dev -> msg_queue_core_ctx . ready_queue ) ) { mtk_v4l2_debug ( 3 , "re-schedule to decode for core: %d" , dev -> msg_queue_core_ctx . ready_num ) ; queue_work ( dev -> core_workqueue , & msg_queue -> core_work ) ; } } 